const notice=document.getElementById('accountNotice'),inviteToken=new URLSearchParams(location.search).get('invite');function showNotice(message,error=false){notice.textContent=message;notice.hidden=false;notice.classList.toggle('error',error)}async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options}),data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data}function switchTab(name){document.querySelectorAll('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===name));document.getElementById('signupForm').hidden=name!=='signup';document.getElementById('loginForm').hidden=name!=='login';if(!inviteToken)notice.hidden=true;history.replaceState({},'',name==='login'?'/login':`/signup${inviteToken?`?invite=${inviteToken}`:''}`)}document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>switchTab(button.dataset.tab)));if(location.pathname==='/login')switchTab('login');if(inviteToken)api(`/api/invites/preview?token=${encodeURIComponent(inviteToken)}`).then(data=>showNotice(`${data.inviterCompany.name} invited you to join their trusted trade network. Create your account to connect automatically.`)).catch(error=>showNotice(error.message,true));document.getElementById('signupForm').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget),capabilities=[...event.currentTarget.querySelectorAll('[name="capability"]:checked')].map(input=>input.value);try{if(!capabilities.length)throw new Error('Choose at least one company capability.');await api('/api/signup',{method:'POST',body:JSON.stringify({fullName:form.get('fullName'),companyName:form.get('companyName'),city:form.get('city'),state:form.get('state'),trades:String(form.get('trades')||'').split(',').map(value=>value.trim()).filter(Boolean),email:form.get('email'),password:form.get('password'),capabilities,inviteToken})});location.href='/dashboard'}catch(error){showNotice(error.message,true)}});document.getElementById('loginForm').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{await api('/api/login',{method:'POST',body:JSON.stringify({email:form.get('email'),password:form.get('password')})});location.href='/dashboard'}catch(error){showNotice(error.message,true)}});fetch('/api/me').then(response=>{if(response.ok)location.href='/dashboard'});
